methods.editarProducto:
{
        const productId = req.params.id;
        const updatedData = req.body;

        try {
            let productRepository = new ProductRepository();
            const updatedProduct = await productRepository.edit(productId, updatedData);
            res.status(200).json({
                status: 200,
                data: updatedProduct
            });
        } catch (error) {
            console.error('Error en editarProducto:', error);
            const errorObj = JSON.parse(error.message);
            res.status(errorObj.status).json(errorObj);
        }
    }

methods.eliminarProducto:
{
        try {
            const { id } = req.params; 
            let productRepository = new ProductRepository();
            await productRepository.remove(id); 
            res.status(204).send();
        } catch (error) {
            const errorObj = JSON.parse(error.message);
            res.status(errorObj.status).json(errorObj);
        }
    }

methods.crearUsuario:
{
        try {
            const errors = validationResult(req);
            if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });


            console.log('Datos para verificar usuario:', req.body);
            const userExist = await this.userRepository.getOneUserByNameEmailOrOauthId(req.body);

            if (userExist) {
                console.log('Ya existe un usuario con ese email o nick');
                return res.status(409).json({ message: 'Usuario ya registrado' });
            }


            const newUser = await this.userRepository.save(req.body);
            return res.status(201).json(newUser);
        } catch (error) {
            const errorObj = JSON.parse(error.message);
            res.status(errorObj.status).json({ message: errorObj.message });
        }
    }

methods.logUsuario:
{
        try {
            const { email, password } = req.body;
            const user = await this.userRepository.getOneUserByNameEmail(email); 

            if (!user) {
                return res.status(404).json({ message: 'Usuario no encontrado' });
            }


            if (password !== user.password) {
                return res.status(401).json({ message: 'Contraseña incorrecta' });
            }

            return res.status(200).json({ message: 'Usuario loggeado', user });
        } catch (error) {
            console.error(error); 
            res.status(500).json({ message: 'Error en el servidor' });
        }
    }

